            return;
        }
        var trackers = loadTrackers({});
        assert.equal(
            trackers.createTracker({}).provider(),
            String(env).toLowerCase().trim(),
            'DEFAULT_TRACKER must drive the provider when the config never mentions a tracker'
        );
    });
});

